try {
  const bRect = delBtn.getBoundingClientRect();
  if (bRect.width < 24 || bRect.height < 24) return false;

  delBtn.focus();
  const bStyle = window.getComputedStyle(delBtn);
  const outlineWidth = parseFloat(bStyle.outlineWidth) || 0;
  if (outlineWidth < 2) return false;

  adapter.onClick({
    target: delBtn,
    isTrusted: true,
    timeStamp: performance.now(),
    detail: 1,
    preventDefault() {},
    stopImmediatePropagation() {}
  });

  const prompt = document.getElementById('ai4a11y-confirm-prompt');
  if (!prompt) return false;

  function getLuminance(rgbStr) {
    const m = rgbStr.match(/\d+/g);
    if (!m) return 0;
    const [r, g, b] = m.slice(0, 3).map(v => {
      const c = Number(v) / 255;
      return c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4);
    });
    return 0.2126 * r + 0.7152 * g + 0.0722 * b;
  }
  function contrast(c1, c2) {
    const l1 = getLuminance(c1);
    const l2 = getLuminance(c2);
    return (Math.max(l1, l2) + 0.05) / (Math.min(l1, l2) + 0.05);
  }

  const pStyle = window.getComputedStyle(prompt);
  const pRatio = contrast(pStyle.color, pStyle.backgroundColor);
  if (pRatio < 4.5) return false;

  const pRect = prompt.getBoundingClientRect();
  if (pRect.left < 0 || pRect.right > window.innerWidth || pRect.top < 0 || pRect.bottom > window.innerHeight) {
    return false;
  }

  const overlaps = !(
    pRect.right <= bRect.left ||
    pRect.left >= bRect.right ||
    pRect.bottom <= bRect.top ||
    pRect.top >= bRect.bottom
  );
  if (overlaps) return false;

  return true;
